<div class="panel"><div class="panel-head"><div><h2>Product comparisons</h2><p>Create side-by-side comparisons using reusable product data and category specifications.</p></div><a class="primary-button" href="<?= e(url('admin/comparisons/new')) ?>">New comparison</a></div><div class="table-wrap"><table><thead><tr><th>Title</th><th>Category</th><th>Products</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if(empty($comparisons)):?><tr><td colspan="6">No comparisons yet.</td></tr><?php endif;?><?php foreach($comparisons as $item):?><tr><td><strong><?= e($item['title']) ?></strong><br><small>/compare/<?= e($item['slug']) ?></small></td><td><?= e($item['category_name']??'—') ?></td><td><?= (int)$item['product_count'] ?></td><td><span class="badge"><?= e($item['status']) ?></span></td><td><?= e((string)$item['updated_at']) ?></td><td><a href="<?= e(url('admin/comparisons/'.(int)$item['id'].'/edit')) ?>">Edit</a><?php if($item['status']==='published'):?> · <a href="<?= e(url('compare/'.$item['slug'])) ?>" target="_blank">View</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>